// BTC via MQTT -> guarda ultimo valor en flow.btc (+ promedio de flujo 5 min)
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || typeof p !== 'object') return null;

const price = Number(p.price);
if (!Number.isFinite(price) || price < 1000) return null;

const now  = Date.now();
const flowv = Number(p.flow_btc_s);
const rssi  = Number(p.rssi);

let samples = context.get('flowSamples') || [];
if (Number.isFinite(flowv)) samples.push({ t: now, v: flowv });
const cutoff = now - 300000;               // ultimos 5 min
samples = samples.filter(s => s.t >= cutoff);
context.set('flowSamples', samples);

let avg = null;
if (samples.length) avg = samples.reduce((a, s) => a + s.v, 0) / samples.length;

flow.set('btc', {
  price: price,
  flow:  Number.isFinite(flowv) ? flowv : null,
  avg:   avg,
  rssi:  Number.isFinite(rssi) ? rssi : null,
  device: p.device || '-',
  ts: now
});
return null;

// Suscribe ticker + trade (compra/venta) de las 3 monedas
const pairs = ['XMR/USD', 'GMX/USD', 'LTC/USD'];
return [[
  { payload: JSON.stringify({ event: 'subscribe', pair: pairs, subscription: { name: 'ticker' } }) },
  { payload: JSON.stringify({ event: 'subscribe', pair: pairs, subscription: { name: 'trade' } }) }
]];

// Kraken WS: ticker (precio/vol) + trade (compra/venta) -> flow context
let d;
try { d = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; }
catch (e) { return null; }

if (!Array.isArray(d)) {
  if (d && d.event === 'subscriptionStatus') {
    node.status({
      fill: d.status === 'subscribed' ? 'green' : 'red', shape: 'dot',
      text: (d.pair || '') + ' ' + ((d.subscription && d.subscription.name) || '') + ' ' + (d.status || '')
    });
  }
  return null;
}

if (d.length < 4) return null;
const chan = d[2];
const pair = String(d[3] || '');
const key = pair === 'XMR/USD' ? 'xmr' : pair === 'GMX/USD' ? 'gmx' : pair === 'LTC/USD' ? 'ltc' : null;
if (!key) return null;
const now = Date.now();

if (chan === 'ticker') {
  const t = d[1] || {};
  if (!t.c || !t.c.length) return null;
  const price = Number(t.c[0]);
  if (!Number.isFinite(price) || price <= 0) return null;
  const prev = flow.get(key) || {};
  flow.set(key, {
    price: price,
    bid: (t.b && t.b.length) ? Number(t.b[0]) : null,
    ask: (t.a && t.a.length) ? Number(t.a[0]) : null,
    vol24:    (t.v && t.v.length > 1) ? Number(t.v[1]) : prev.vol24,
    trades24: (t.t && t.t.length > 1) ? Number(t.t[1]) : prev.trades24,
    ts: now
  });
} else if (chan === 'trade') {
  const list = Array.isArray(d[1]) ? d[1] : [];
  let arr = flow.get('trades_' + key) || [];
  for (const tr of list) {
    const v = Number(tr[1]);            // volumen
    const s = tr[3];                    // 'b' compra / 's' venta
    if (Number.isFinite(v)) arr.push({ t: now, v: v, s: s });
  }
  arr = arr.filter(x => x.t >= now - 300000);   // ventana 5 min
  if (arr.length > 3000) arr = arr.slice(-3000);
  flow.set('trades_' + key, arr);
}
return null;

// Latido REST: ultimo precio + vol24 de Kraken (aunque el WS este mudo/caido)
const d = msg.payload;
if (!d || !d.result || (Array.isArray(d.error) && d.error.length)) {
  node.status({ fill: 'red', shape: 'ring', text: 'REST error' });
  return null;
}
const now = Date.now();
const res = d.result;
let n = 0;
for (const kk of Object.keys(res)) {
  const t = res[kk];
  if (!t || !t.c || !t.c.length) continue;
  const price = Number(t.c[0]);
  if (!Number.isFinite(price) || price <= 0) continue;
  const K = kk.toUpperCase();
  const key = K.indexOf('XMR') >= 0 ? 'xmr' : K.indexOf('GMX') >= 0 ? 'gmx' : K.indexOf('LTC') >= 0 ? 'ltc' : null;
  if (!key) continue;
  const prev = flow.get(key) || {};
  flow.set(key, {
    price: price,
    bid: (t.b && t.b.length) ? Number(t.b[0]) : null,
    ask: (t.a && t.a.length) ? Number(t.a[0]) : null,
    vol24:    (t.v && t.v.length > 1) ? Number(t.v[1]) : prev.vol24,
    trades24: (t.t && t.t.length > 1) ? Number(t.t[1]) : prev.trades24,
    ts: now
  });
  n++;
}
node.status({ fill: 'green', shape: 'dot', text: 'REST ok ' + n + ' · ' + new Date(now).toLocaleTimeString() });
return null;

// Cada 5 s: panel resumen + tarjetas con min/max, EMA, Δ, vol y presion
const now = Date.now();
const staleMs = (Number(global.get('cryptoStaleSec')) || 600) * 1000;

const ringOf = k => flow.get('hist_' + k) || [];

function chgWin(k, price, ms) {
  const ring = ringOf(k);
  if (!ring.length) return null;
  const target = now - ms;
  let ref = ring[0];
  for (const pt of ring) { if (pt.t <= target) ref = pt; else break; }
  if (!ref || !Number.isFinite(ref.p) || ref.p === 0) return null;
  return (price - ref.p) / ref.p * 100;
}
function hilo(k, price) {
  const ring = ringOf(k);
  let hi = null, lo = null;
  for (const pt of ring) { if (hi == null || pt.p > hi) hi = pt.p; if (lo == null || pt.p < lo) lo = pt.p; }
  if (Number.isFinite(price)) { if (hi == null || price > hi) hi = price; if (lo == null || price < lo) lo = price; }
  let pos = 50;
  if (hi != null && lo != null && hi > lo) pos = (price - lo) / (hi - lo) * 100;
  return { hi: hi, lo: lo, pos: Math.max(0, Math.min(100, pos)) };
}
function pressure(k) {
  const arr = flow.get('trades_' + k) || [];
  let b = 0, s = 0;
  for (const x of arr) { if (x.s === 'b') b += x.v; else if (x.s === 's') s += x.v; }
  const tot = b + s;
  return tot > 0 ? { buy: b, sell: s, buyPct: b / tot * 100 } : { buy: 0, sell: 0, buyPct: null };
}

const map = [['btc','BTC'], ['xmr','XMR'], ['gmx','GMX'], ['ltc','LTC']];
const sum = {}, cards = {};
for (const [k, sym] of map) {
  const q = flow.get(k);
  if (q && Number.isFinite(q.price)) {
    const hl = hilo(k, q.price);
    const pr = pressure(k);
    const item = {
      symbol: sym, price: q.price,
      change:   chgWin(k, q.price, 3600000),
      change24: chgWin(k, q.price, 86400000),
      hi: hl.hi, lo: hl.lo, pos: hl.pos,
      age:   q.ts ? Math.round((now - q.ts) / 1000) : null,
      stale: q.ts ? (now - q.ts > staleMs) : true,
      bid: q.bid != null ? q.bid : null,
      ask: q.ask != null ? q.ask : null,
      vol24:    q.vol24    != null ? q.vol24    : null,
      trades24: q.trades24 != null ? q.trades24 : null,
      flow: q.flow != null ? q.flow : null,
      avg:  q.avg  != null ? q.avg  : null,
      rssi: q.rssi != null ? q.rssi : null,
      device: q.device || null,
      buyPct: pr.buyPct, buy: pr.buy, sell: pr.sell
    };
    sum[k] = item; cards[k] = { payload: item };
  } else { sum[k] = null; cards[k] = null; }
}
return [{ payload: sum }, cards.btc, cards.xmr, cards.gmx, cards.ltc];

// Cada 1 s: precio actual a los graficos "en vivo" (efimeros, NO se guardan)
const now = Date.now();
const staleMs = (Number(global.get('cryptoStaleSec')) || 600) * 1000;
function pt(k, sym) {
  const q = flow.get(k);
  if (!q || !Number.isFinite(q.price)) return null;
  if (q.ts && (now - q.ts) > staleMs) return null;
  return { payload: q.price, topic: sym };
}
return [pt('btc','BTC'), pt('xmr','XMR'), pt('gmx','GMX'), pt('ltc','LTC')];

// Cada 3 min: precio + EMA al grafico y append a disco (varios dias)
const now = Date.now();
const base = global.get('cryptoHistBase') || 'cryptohist/';
const N = Number(global.get('cryptoEmaN')) || 20;
const kk = 2 / (N + 1);
const map = [['btc','BTC'], ['xmr','XMR'], ['gmx','GMX'], ['ltc','LTC']];

const files = [];
const charts = { btc: null, xmr: null, gmx: null, ltc: null };

for (const [k, sym] of map) {
  const q = flow.get(k);
  if (!q || !Number.isFinite(q.price)) continue;
  if (q.ts && (now - q.ts) > 120000) continue;   // dato viejo: no lo registro
  const p = q.price;

  let ring = flow.get('hist_' + k) || [];
  ring.push({ t: now, p: p });
  const cut = now - 86400000;
  ring = ring.filter(r => r.t >= cut);
  if (ring.length > 1500) ring = ring.slice(-1500);
  flow.set('hist_' + k, ring);

  let ema = flow.get('ema_' + k);
  ema = (ema == null) ? p : (p * kk + ema * (1 - kk));
  flow.set('ema_' + k, ema);

  files.push({ filename: base + sym + '.log', payload: JSON.stringify({ t: now, p: p }) });
  charts[k] = [ { payload: p, topic: sym }, { payload: ema, topic: sym + ' EMA' } ];
}

return [files, charts.btc, charts.xmr, charts.gmx, charts.ltc];

// Pide leer el historial de cada moneda (una vez al arrancar)
const base = global.get('cryptoHistBase') || 'cryptohist/';
return [ ['BTC','XMR','GMX','LTC'].map(sym => ({ filename: base + sym + '.log', coin: sym })) ];

// Siembra el grafico con historial guardado: precio + EMA reconstruida
const coin = msg.coin || '?';
let txt = msg.payload;
if (Buffer.isBuffer(txt)) txt = txt.toString('utf8');
if (typeof txt !== 'string' || !txt.length) return null;

const now = Date.now();
const days = Number(global.get('cryptoViewDays')) || 3;
const cut = now - days * 86400000;

const pts = [];
for (const ln of txt.split(/\r?\n/)) {
  if (!ln) continue;
  let o; try { o = JSON.parse(ln); } catch (e) { continue; }
  if (!o || !Number.isFinite(o.t) || !Number.isFinite(o.p)) continue;
  if (o.t < cut) continue;
  pts.push({ x: o.t, y: o.p });
}
if (!pts.length) return null;
pts.sort((a, b) => a.x - b.x);

const N = Number(global.get('cryptoEmaN')) || 20;
const kk = 2 / (N + 1);
let ema = null;
const emaPts = [];
for (const pt of pts) { ema = (ema == null) ? pt.y : (pt.y * kk + ema * (1 - kk)); emaPts.push({ x: pt.x, y: ema }); }

flow.set('ema_' + coin.toLowerCase(), ema);
flow.set('hist_' + coin.toLowerCase(), pts.slice(-1500).map(p => ({ t: p.x, p: p.y })));

// downsample (mismos indices para precio y EMA)
const MAX = 600;
let idx = pts.map((_, i) => i);
if (pts.length > MAX) { const step = Math.ceil(pts.length / MAX); idx = idx.filter(i => i % step === 0); }
const dsP = idx.map(i => pts[i]);
const dsE = idx.map(i => emaPts[i]);

msg.payload = [{ series: [coin, coin + ' EMA'], data: [dsP, dsE], labels: ['', ''] }];
msg.topic = coin;
return msg;

// Pide leer cada archivo para recortarlo (retencion en dias)
const base = global.get('cryptoHistBase') || 'cryptohist/';
return [ ['BTC','XMR','GMX','LTC'].map(sym => ({ filename: base + sym + '.log', coin: sym })) ];

// Deja solo los ultimos N dias en el archivo (evita que crezca sin fin)
let txt = msg.payload;
if (Buffer.isBuffer(txt)) txt = txt.toString('utf8');
if (typeof txt !== 'string' || !txt.length) return null;

const keep = Number(global.get('cryptoKeepDays')) || 7;
const cut = Date.now() - keep * 86400000;

const kept = [];
for (const ln of txt.split(/\r?\n/)) {
  if (!ln) continue;
  let o; try { o = JSON.parse(ln); } catch (e) { continue; }
  if (!o || !Number.isFinite(o.t)) continue;
  if (o.t < cut) continue;
  kept.push(JSON.stringify({ t: o.t, p: o.p }));
}
msg.payload = kept.join('\n');
return msg;
